using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>()
var options = new JsonSerializerOptions { TypeInfoResolver = JsonTypeInfoResolver.Combine() };
options.MakeReadOnly();          // required before querying metadata

// Populate the resolver so "int" metadata is available
var defaultOpts = new JsonSerializerOptions(JsonSerializerDefaults.Web);
defaultOpts.MakeReadOnly(populateMissingResolver: true);

// --- Demo 1: GetTypeInfo<T>() returns JsonTypeInfo<T> directly ---
JsonTypeInfo<int> intInfo = defaultOpts.GetTypeInfo<int>();
Console.WriteLine($"1) Got typed metadata  : {intInfo.Type.Name}, compile-time type = JsonTypeInfo<int>");

// --- Demo 2: TryGetTypeInfo for a type that IS resolvable ---
if (defaultOpts.TryGetTypeInfo<int>(out JsonTypeInfo<int>? probed))
    Console.WriteLine($"2) TryGetTypeInfo<int>  : found – {probed.Type.Name}");
else
    Console.WriteLine("2) TryGetTypeInfo<int>  : not found");

// --- Demo 3: TryGetTypeInfo for a type that is NOT resolvable ---
// Use the empty-resolver options so nothing resolves
if (options.TryGetTypeInfo<string>(out JsonTypeInfo<string>? probed2))
    Console.WriteLine($"3) TryGetTypeInfo<string>: found – {probed2.Type.Name}");
else
    Console.WriteLine("3) TryGetTypeInfo<string>: not found (no resolver for this type)");
CSHARP
